public class Solution {
    public boolean isHappy(int n) {
        // не детектирует цикл — возвращает false если зашли в цикл n=4
        for (int i = 0; i < 5; i++) {
            int s = 0;
            while (n > 0) { int d = n%10; s += d*d; n /= 10; }
            n = s; if (n == 1) return true;
        }
        return false;  // слишком рано прерываемся
    }
}
